INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 1, 'STEP 1 - SOAK THE RICE NOODLES');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 2, 'Soak the rice noodles overnight untill they are soft');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 3, 'STEP 2 - BOIL THE RICE NOODLES');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 4, 'Boil the noodles for 10-15 minutes and then rinse with cold water to stop the cooking process of the noodles.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 5, 'STEP 3 -MARINATING THE SHRIMP');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 6, 'In a bowl add the shrimp, egg, 1 pinch of white pepper, 1 Teaspoon of sesame seed oil, 1 Tablespoon corn starch and 1 tablespoon of oil');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 7, 'Mix together well');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 8, 'STEP 4 - STIR FRY');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 9, 'In a wok add 2 Tablespoons of oil, shrimp and stir fry them until it is golden brown');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 10, 'Set the shrimp aside');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 11, 'Add 1 Tablespoon of oil to the work and then add minced garlic, ginger and all of the vegetables.');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 12, 'Add the noodles to the wok');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 13, 'Next add sherry cooking wine, oyster sauce, sugar, vinegar, sesame seed oil, 1 pinch white pepper, and soy sauce');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 14, 'Add back in the shrimp');
INSERT INTO recipe_steps (recipe_id, position, instruction) VALUES ('00000000-0000-4000-8000-00000000ced9', 15, 'To thicken the sauce, whisk together 1 Tablespoon of corn starch and 2 Tablespoon of water in a bowl and slowly add to your stir-fry until it''s the right thickness.');
INSERT INTO recipes (id, name, description, meal_type, servings) VALUES ('00000000-0000-4000-8000-00000000d07f', 'Shrimp With Snow Peas', 'Danie: Chinese. Źródło: TheMealDB', 'lunch', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d07f', 'Cornstarch', 10, 'ml', 1);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d07f', 'Dry sherry', 15, 'ml', 2);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d07f', 'Kosher Salt', 3, 'ml', 3);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d07f', 'Shrimp', 453, 'g', 4);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d07f', 'Peanut Oil', 30, 'ml', 5);
INSERT INTO recipe_ingredients (recipe_id, ingredient_label, quantity, unit, position) VALUES ('00000000-0000-4000-8000-00000000d07f', 'Ground Ginger', 15, 'ml', 6);
